Object.assign(translations['pt-BR'],{academyGuideEyebrow:'AURORA · GUIA DE CAMPO',academyGuideTitle:'Aprender também é traçar uma rota.',academyGuideCopy:'Eu explico o sinal, você toma a decisão e o mapa responde ao que aprendeu.',academyQuestions:'desafios',academyMaps:'mapas',sequenceInstruction:'Toque nos cartões na ordem correta para reconstruir o processo.',choiceInstruction:'Escolha a leitura mais consistente com as evidências.',modeLabels:{choice:'Leitura de sinal',sequence:'Sequência de descoberta'},courseProgress:'cartas dominadas',courseLocked:'Complete a etapa anterior para abrir esta rota.',academyDialogues:{fundamental:['Antes de decorar nomes, veja como a luz se comporta. É ela que conta a primeira história do céu.','Uma imagem não é só bonita: textura, sombra e cor são pistas que podemos testar.','Você não precisa acertar depressa. Precisa aprender a justificar a rota.'],medium:['Agora o mapa ganha profundidade. Distância, tempo e gravidade começam a conversar.','Cada instrumento enxerga uma parte diferente do universo. Compare sinais, não adivinhe.','Json, uma boa rota sempre cruza mais de uma referência.'],advanced:['Aqui a matemática não substitui a imaginação: ela nos permite verificar a imaginação.','Leia a fórmula como uma história sobre grandezas que mudam juntas.','Medição, modelo e incerteza: esta é a navegação de um físico.'],higher:['No limite do observável, perguntas simples exigem ideias corajosas e evidências cuidadosas.','Quasares, lentes e expansão: o universo deixa pistas mesmo quando não podemos tocá-lo.','Uma hipótese forte ainda precisa sobreviver aos dados.']},constellationDialogues:['Se eu reconhecer o padrão, consigo marcar nossa posição sem fingir que as estrelas estão próximas.', 'O desenho é uma perspectiva vista da Terra. O mapa é útil justamente porque sabemos que ele é uma convenção.', 'Cada estrela escolhida acrescenta uma linha à rota de Aurora.'],constellationCompleteAll:'Você reuniu todo o Atlas Aurora. Agora pode revisitar qualquer mapa.',crowns:{none:'Em formação',bronze:'Coroa de bronze',silver:'Coroa de prata',gold:'Coroa dourada'}});
Object.assign(translations.en,{academyGuideEyebrow:'AURORA · FIELD GUIDE',academyGuideTitle:'Learning is also plotting a route.',academyGuideCopy:'I explain the signal, you make the call, and the map responds to what you learned.',academyQuestions:'challenges',academyMaps:'maps',sequenceInstruction:'Tap the cards in the correct order to rebuild the process.',choiceInstruction:'Choose the reading most consistent with the evidence.',modeLabels:{choice:'Signal reading',sequence:'Discovery sequence'},courseProgress:'cards mastered',courseLocked:'Complete the previous stage to open this route.',academyDialogues:{fundamental:['Before memorizing names, watch how light behaves. It tells the sky’s first story.','An image is not only beautiful: texture, shadow and colour are clues we can test.','You do not need to be fast. You need to learn how to justify the route.'],medium:['The map now gains depth. Distance, time and gravity begin to talk to each other.','Every instrument sees a different part of the universe. Compare signals; do not guess.','Json, a good route always cross-checks more than one reference.'],advanced:['Math does not replace imagination here: it lets us test imagination.','Read a formula as a story about quantities changing together.','Measurement, model and uncertainty: that is a physicist’s navigation.'],higher:['At the edge of what we can observe, simple questions require bold ideas and careful evidence.','Quasars, lenses and expansion: the universe leaves clues even when we cannot touch it.','A strong hypothesis still has to survive the data.']},constellationDialogues:['If I recognize the pattern, I can mark our position without pretending the stars are close together.', 'The drawing is a perspective seen from Earth. The map is useful precisely because we know it is a convention.', 'Every chosen star adds a line to Aurora’s route.'],constellationCompleteAll:'You assembled the whole Aurora Atlas. You can now revisit any map.',crowns:{none:'In training',bronze:'Bronze crown',silver:'Silver crown',gold:'Golden crown'}});
translations['pt-BR'].studyBanks.fundamental.push(
{type:'SEQUÊNCIA',mode:'sequence',title:'Como a Lua aparece iluminada para nós?',context:'Organize o caminho da luz; assim as fases deixam de parecer uma mudança na própria Lua.',sequence:['O Sol emite luz','A superfície lunar reflete parte dessa luz','A luz refletida chega aos olhos do observador'],explain:'A Lua não produz luz própria. A parte que vemos depende de como Sol, Terra e Lua estão posicionados.',source:'https://science.nasa.gov/moon/'},
{type:'FASES',title:'O que causa as fases da Lua?',context:'Vesper chama a sombra da Terra para toda fase. Aurora pede uma leitura geométrica mais precisa.',answers:['A Lua muda a quantidade de luz que produz','Vemos porções diferentes da metade iluminada conforme a posição relativa','Nuvens espaciais encobrem partes da Lua'],correct:1,explain:'Metade da Lua está iluminada pelo Sol; da Terra, vemos frações diferentes dessa metade conforme a geometria orbital.',source:'https://science.nasa.gov/moon/'},
{type:'IMAGEM',title:'Qual imagem mostra Marte?',context:'Procure por uma superfície rochosa avermelhada e crateras; não use o tamanho aparente como pista.',image:'assets/nasa/mars-viking.jpg',answers:['Júpiter','Marte','A Lua'],correct:1,explain:'Marte é um planeta rochoso de superfície oxidada. As imagens Viking ajudaram a registrar seu relevo e atmosfera.',source:'https://science.nasa.gov/mars/'},
{type:'ESTAÇÕES',title:'Por que existem estações na Terra?',context:'A distância ao Sol muda pouco ao longo do ano; o fator decisivo é outro.',answers:['Porque o eixo de rotação terrestre é inclinado','Porque a Terra recebe mais luz ao se afastar do Sol','Porque o Sol fica mais quente em dezembro'],correct:0,explain:'A inclinação do eixo muda o ângulo e a duração da luz solar em cada hemisfério durante a órbita.',source:'https://science.nasa.gov/earth/facts/'}
);
translations['pt-BR'].studyBanks.medium.push(
{type:'SEQUÊNCIA',mode:'sequence',title:'Como transformar uma observação em rota?',context:'Json precisa decidir sem confundir uma impressão inicial com uma conclusão.',sequence:['Observar mais de uma referência','Comparar as medidas com o mapa','Escolher a manobra baseada nos dados'],explain:'Navegação confiável começa com observações, compara referências e só então decide uma ação.',source:'https://science.nasa.gov/learn/basics-of-space-flight/'},
{type:'VELOCIDADE',title:'O que significa velocidade de escape?',context:'Não é uma velocidade para “desligar” a gravidade, mas para não voltar sem propulsão adicional.',answers:['A maior velocidade dentro da atmosfera','A velocidade mínima para escapar gravitacionalmente sem propulsão adicional','A velocidade que faz uma órbita circular perfeita'],correct:1,explain:'A velocidade de escape depende da massa e do raio do corpo; ela descreve um limite de energia gravitacional.',source:'https://science.nasa.gov/learn/basics-of-space-flight/chapter2-1/'},
{type:'IMAGEM',title:'O que é Europa nesta imagem?',context:'Ela fica próxima de Júpiter, mas não é um planeta: observe sua superfície clara e rachada.',image:'assets/nasa/europa-juno.jpg',answers:['Uma lua de Júpiter','A Grande Mancha Vermelha','Um anel de Saturno'],correct:0,explain:'Europa é uma lua gelada de Júpiter. Dados de missões sugerem um oceano sob sua crosta de gelo.',source:'https://science.nasa.gov/jupiter/moons/europa/'},
{type:'TELESCÓPIO',title:'Por que um telescópio maior pode ajudar?',context:'Mais abertura não cria mais luz; ela coleta mais da luz que já está chegando.',answers:['Porque coleta mais luz e pode revelar objetos mais fracos','Porque aproxima fisicamente os planetas','Porque elimina qualquer distorção da atmosfera'],correct:0,explain:'A área coletora maior permite detectar sinais fracos; resolução e atmosfera ainda importam na qualidade da imagem.',source:'https://science.nasa.gov/universe/telescopes/'}
);
translations['pt-BR'].studyBanks.advanced.push(
{type:'SEQUÊNCIA',mode:'sequence',title:'Como um trânsito pode revelar um exoplaneta?',context:'Organize as observações que transformam uma queda sutil de brilho em evidência.',sequence:['Medir continuamente o brilho da estrela','Encontrar quedas periódicas e pequenas','Testar se o padrão é compatível com um planeta em trânsito'],explain:'Quando um planeta passa à frente da estrela, ele pode reduzir um pouco sua luz observada. Repetição e testes evitam falsos positivos.',source:'https://science.nasa.gov/exoplanets/'},
{type:'GRAVITAÇÃO',title:'Se a distância entre dois corpos dobra, o que acontece com F?',context:'Use a dependência inversa de r² sem mudar as massas.',formula:'F = G M m / r²',answers:['F fica quatro vezes maior','F cai para um quarto','F cai pela metade'],correct:1,explain:'Como r está ao quadrado no denominador, dobrar a distância torna r² quatro vezes maior e reduz F para um quarto.',source:'https://science.nasa.gov/learn/basics-of-space-flight/chapter2-1/'},
{type:'LUMINOSIDADE',title:'Uma estrela mais quente tende a ter pico de emissão...',context:'Use a lei de Wien para relacionar temperatura e comprimento de onda.',formula:'λₘáx T = b',answers:['Em comprimentos de onda menores','No mesmo comprimento de onda','Em comprimentos de onda maiores'],correct:0,explain:'Para manter o produto aproximadamente constante, maior temperatura corresponde a menor comprimento de onda no pico.',source:'https://science.nasa.gov/universe/stars/'},
{type:'ESPECTRO',title:'Para que servem linhas espectrais?',context:'Elas funcionam como assinaturas da matéria quando a luz é separada por comprimento de onda.',answers:['Medir apenas a idade de planetas','Identificar elementos e inferir movimento ou condições físicas','Fazer estrelas parecerem coloridas em imagens'],correct:1,explain:'Linhas de emissão e absorção estão ligadas a transições atômicas; seus padrões ajudam a inferir composição, temperatura e velocidade.',source:'https://science.nasa.gov/universe/the-electromagnetic-spectrum/'}
);
translations['pt-BR'].studyBanks.higher.push(
{type:'SEQUÊNCIA',mode:'sequence',title:'Como a expansão aparece em uma observação?',context:'Json organiza a pista que liga espectros de galáxias ao modelo cosmológico.',sequence:['Medir linhas conhecidas no espectro de uma galáxia','Comparar com o comprimento de onda medido em laboratório','Interpretar o deslocamento para o vermelho com outras evidências'],explain:'O redshift compara linhas espectrais observadas e conhecidas. Em grande escala, ele é uma evidência da expansão do espaço.',source:'https://science.nasa.gov/universe/the-big-bang/'},
{type:'LENTE',title:'O que é lente gravitacional?',context:'A gravidade altera a geometria do espaço-tempo, e a luz pode seguir essa curvatura.',answers:['Uma lente feita de poeira interestelar','A curvatura da luz por uma massa, podendo ampliar objetos distantes','Uma ilusão causada pelo telescópio'],correct:1,explain:'Massas grandes podem curvar trajetórias luminosas, formando arcos, imagens múltiplas ou ampliação de objetos mais distantes.',source:'https://science.nasa.gov/universe/black-holes/'},
{type:'FÓSSIL CÓSMICO',title:'O que é a radiação cósmica de fundo?',context:'Ela não é luz de estrelas atuais, mas um sinal remanescente do universo jovem.',answers:['Radiação térmica remanescente do universo primitivo','Energia produzida por todos os quasares juntos','Uma camada de partículas em torno da Terra'],correct:0,explain:'A radiação cósmica de fundo é observada como um brilho em micro-ondas quase uniforme, com pequenas variações importantes.',source:'https://science.nasa.gov/universe/the-big-bang/'},
{type:'HORIZONTE',title:'Por que o horizonte de eventos é especial?',context:'Não é uma superfície sólida: é uma fronteira causal no modelo de buraco negro.',answers:['Porque marca onde a luz não consegue mais escapar para um observador distante','Porque toda matéria deixa de ter massa','Porque a gravidade deixa de agir'],correct:0,explain:'Depois do horizonte, trajetórias que apontariam para fora ainda não conseguem alcançar o observador distante.',source:'https://science.nasa.gov/universe/black-holes/'}
);
translations.en.studyBanks.fundamental.push(
{type:'SEQUENCE',mode:'sequence',title:'How does the Moon appear illuminated to us?',context:'Arrange light’s path; that makes phases stop looking like a change in the Moon itself.',sequence:['The Sun emits light','The lunar surface reflects some of that light','Reflected light reaches the observer’s eyes'],explain:'The Moon does not make its own light. The portion we see depends on the Sun–Earth–Moon geometry.',source:'https://science.nasa.gov/moon/'},
{type:'PHASES',title:'What causes the Moon’s phases?',context:'Vesper calls every phase Earth’s shadow. Aurora asks for a more precise geometric reading.',answers:['The Moon changes how much light it produces','We see different portions of its lit half as the relative positions change','Space clouds cover parts of the Moon'],correct:1,explain:'Half of the Moon is lit by the Sun; from Earth we see different fractions of that half as the geometry changes.',source:'https://science.nasa.gov/moon/'},
{type:'IMAGE',title:'Which image shows Mars?',context:'Look for a reddish rocky surface and craters; do not use apparent size as your clue.',image:'assets/nasa/mars-viking.jpg',answers:['Jupiter','Mars','The Moon'],correct:1,explain:'Mars is a rocky planet with an oxidized surface. Viking images recorded its terrain and atmosphere.',source:'https://science.nasa.gov/mars/'},
{type:'SEASONS',title:'Why does Earth have seasons?',context:'Distance to the Sun changes little through the year; another factor is decisive.',answers:['Because Earth’s rotation axis is tilted','Because Earth gets more light when it moves away from the Sun','Because the Sun gets hotter in December'],correct:0,explain:'The tilted axis changes the angle and duration of sunlight in each hemisphere during the orbit.',source:'https://science.nasa.gov/earth/facts/'}
);
translations.en.studyBanks.medium.push(
{type:'SEQUENCE',mode:'sequence',title:'How do you turn an observation into a route?',context:'Json needs to decide without confusing a first impression with a conclusion.',sequence:['Observe more than one reference','Compare measurements with the map','Choose a maneuver based on the data'],explain:'Reliable navigation starts with observations, compares references, then makes an action choice.',source:'https://science.nasa.gov/learn/basics-of-space-flight/'},
{type:'VELOCITY',title:'What does escape velocity mean?',context:'It is not a speed that “turns off” gravity, but a way not to return without further propulsion.',answers:['The greatest speed in the atmosphere','The minimum speed to escape gravitationally without extra propulsion','The speed that makes a perfect circular orbit'],correct:1,explain:'Escape velocity depends on a body’s mass and radius; it describes a gravitational energy threshold.',source:'https://science.nasa.gov/learn/basics-of-space-flight/chapter2-1/'},
{type:'IMAGE',title:'What is Europa in this image?',context:'It is near Jupiter, but it is not a planet: inspect its pale, cracked surface.',image:'assets/nasa/europa-juno.jpg',answers:['A moon of Jupiter','The Great Red Spot','A ring of Saturn'],correct:0,explain:'Europa is an icy moon of Jupiter. Mission data suggests an ocean beneath its icy crust.',source:'https://science.nasa.gov/jupiter/moons/europa/'},
{type:'TELESCOPE',title:'Why can a larger telescope help?',context:'More aperture does not create light; it collects more of the light already arriving.',answers:['It collects more light and can reveal fainter objects','It physically brings planets closer','It removes every atmospheric distortion'],correct:0,explain:'A larger collecting area can detect weak signals; resolution and atmosphere still affect image quality.',source:'https://science.nasa.gov/universe/telescopes/'}
);
translations.en.studyBanks.advanced.push(
{type:'SEQUENCE',mode:'sequence',title:'How can a transit reveal an exoplanet?',context:'Arrange the observations that turn a subtle brightness dip into evidence.',sequence:['Continuously measure a star’s brightness','Find small periodic dips','Test whether the pattern fits a transiting planet'],explain:'When a planet passes in front of a star, it can slightly reduce observed light. Repetition and tests avoid false positives.',source:'https://science.nasa.gov/exoplanets/'},
{type:'GRAVITY',title:'If the distance between two bodies doubles, what happens to F?',context:'Use the inverse r² relationship while keeping masses unchanged.',formula:'F = G M m / r²',answers:['F becomes four times larger','F falls to one quarter','F falls by half'],correct:1,explain:'Because r is squared in the denominator, doubling distance makes r² four times larger and reduces F to one quarter.',source:'https://science.nasa.gov/learn/basics-of-space-flight/chapter2-1/'},
{type:'LUMINOSITY',title:'A hotter star tends to peak...',context:'Use Wien’s law to relate temperature and wavelength.',formula:'λmax T = b',answers:['At shorter wavelengths','At the same wavelength','At longer wavelengths'],correct:0,explain:'To keep the product roughly constant, greater temperature corresponds to a shorter peak wavelength.',source:'https://science.nasa.gov/universe/stars/'},
{type:'SPECTRUM',title:'What are spectral lines for?',context:'They work like matter signatures when light is separated by wavelength.',answers:['Only measuring the age of planets','Identifying elements and inferring motion or physical conditions','Making stars look colourful in images'],correct:1,explain:'Emission and absorption lines come from atomic transitions; their patterns help infer composition, temperature and speed.',source:'https://science.nasa.gov/universe/the-electromagnetic-spectrum/'}
);
translations.en.studyBanks.higher.push(
{type:'SEQUENCE',mode:'sequence',title:'How does expansion appear in an observation?',context:'Json arranges the clue connecting galaxy spectra to a cosmological model.',sequence:['Measure known lines in a galaxy spectrum','Compare them with laboratory wavelengths','Interpret redshift with other evidence'],explain:'Redshift compares observed and known spectral lines. On large scales, it is evidence for space expansion.',source:'https://science.nasa.gov/universe/the-big-bang/'},
{type:'LENS',title:'What is gravitational lensing?',context:'Gravity changes spacetime geometry, and light can follow that curvature.',answers:['A lens made of interstellar dust','Light bent by mass, which can magnify distant objects','An illusion caused by a telescope'],correct:1,explain:'Large masses can bend light paths, forming arcs, multiple images, or magnification of more distant objects.',source:'https://science.nasa.gov/universe/black-holes/'},
{type:'COSMIC FOSSIL',title:'What is the cosmic microwave background?',context:'It is not light from present stars, but a remnant signal from the young universe.',answers:['Thermal radiation left from the early universe','Energy made by every quasar together','A layer of particles around Earth'],correct:0,explain:'The cosmic microwave background appears as nearly uniform microwave glow with important small variations.',source:'https://science.nasa.gov/universe/the-big-bang/'},
{type:'HORIZON',title:'Why is the event horizon special?',context:'It is not a solid surface: it is a causal boundary in a black-hole model.',answers:['It marks where light can no longer escape to a distant observer','All matter loses mass there','Gravity stops acting there'],correct:0,explain:'Past the horizon, even paths pointing outward cannot reach a distant observer.',source:'https://science.nasa.gov/universe/black-holes/'}
);
